var i=[{title:`Das Wesentliche schützen`,text:`Entscheide zuerst, wofür die Einheit hauptsächlich da ist, etwa Krafttraining oder aerobe Kondition. Verbringe ein paar Minuten damit, die Bewegungen aufzuwärmen, die du nutzt, und konzentriere dich dann auf ein oder zwei Hauptübungen. Auch eine kurze Einheit braucht Raum für sichere Technik und genug Pause, wenn die Lasten schwer sind.`},{title:`Zeitsparende Formate`,text:`Supersätze kombinieren Übungen, die nicht konkurrieren, etwa Rudern und Kniebeugen, und abwechselnde Sätze verkürzen Wartezeiten. Zirkel können einfache Bewegungen für allgemeine Fitness aneinanderreihen. Hetze nicht zwischen harten, technischen schweren Hebungen, wenn dich die Ermüdung die Kontrolle kostet.`},{title:`Beispiel`,text:`Wärme dich für eine 15-minütige Ganzkörpereinheit kurz auf, wechsle zwei oder drei kontrollierte Sätze Stuhl-Kniebeugen und Schräg-Liegestütze ab und beende die Einheit mit einem Ruderzug oder Plank. Passe Wiederholungen und Pause an das an, was du jetzt kannst. An einem anderen Tag können ein zügiger Spaziergang oder eine leichte Radtour deine Kondition unterstützen.`},{title:`Kurze Einheiten summieren sich`,text:`Kurze Aktivitätseinheiten zählen zu deiner Wochensumme. Mache Einheiten nur dann länger, wenn es hilft und in dein Leben passt. Wenn längere Blöcke nicht möglich sind, können regelmäßige kurze Einheiten deine Routine wirksam halten.`},{title:`TrainUp nutzen`,text:`Lege im Profil Einheitendauer und bevorzugte Trainingstage passend zu der Zeit fest, die du wirklich hast, und ändere sie, wann immer sich dein Zeitplan ändert.`}];var t=[{label:`Praktische Hinweise des ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: Gehen für die Gesundheit`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};